-- SQL SEED DUMP FOR SUPABASE (20 PRODUCTOS + 12 MESES DE VENTAS DIARIAS 20-25 VENTAS/DIA)
BEGIN;
-- PROVEEDORES
ON CONFLICT (id) DO UPDATE SET nombre = EXCLUDED.nombre;
-- 20 NUEVOS PRODUCTOS
ON CONFLICT (id) DO UPDATE SET stock = EXCLUDED.stock, proveedor_id = EXCLUDED.proveedor_id;
-- ASIGNAR PROVEEDORES A PRODUCTOS ANTERIORES QUE NO TENGAN PROVEEDOR
UPDATE public.productos SET proveedor_id = 1 WHERE proveedor_id IS NULL AND id % 5 = 0;
UPDATE public.productos SET proveedor_id = 2 WHERE proveedor_id IS NULL AND id % 5 = 1;
UPDATE public.productos SET proveedor_id = 3 WHERE proveedor_id IS NULL AND id % 5 = 2;
UPDATE public.productos SET proveedor_id = 4 WHERE proveedor_id IS NULL AND id % 5 = 3;
UPDATE public.productos SET proveedor_id = 5 WHERE proveedor_id IS NULL AND id % 5 = 4;
-- VENTAS Y VENTA_ITEMS DE 12 MESES (20 A 25 VENTAS POR DIA)


COMMIT;
